CREATE OR REPLACE FUNCTION public.mission_staff_resume_identical_role_v1(p_session uuid, p_failed_director uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  m public.master_v2_sessions;
  run public.mission_run_state;
  current_work mission_generic_owner.work_items;
  current_window mission_generic_owner.unified_source_windows;
  previous_batch mission_generic_owner.unified_batches;
  previous_window mission_generic_owner.unified_source_windows;
  previous_director mission_generic_owner.work_items;
  previous_writer mission_generic_owner.work_items;
  previous_receipt mission_narrative_internal.dispatch_receipts;
  selected_old jsonb;
  selected_new jsonb;
  recovered_decision jsonb;
  mapped_roles jsonb := '[]'::jsonb;
  mapped_evidence jsonb := '[]'::jsonb;
  evidence jsonb;
  old_role uuid;
  new_role uuid;
  matching_count integer;
  recovered jsonb;
  new_writer mission_generic_owner.work_items;
  run_binding mission_generic_owner.run_bindings;
  writer_payload jsonb;
begin
  if p_session is null or p_failed_director is null then
    raise exception 'MSR_INPUT_REQUIRED' using errcode='22023';
  end if;
  m := mission_generic_owner.staff_fato_regen_scope(p_session, auth.uid());
  perform 1 from mission_generic_owner.role_window_cursors
    where master_session_id=p_session for update;
  if not found then
    raise exception 'MSR_ROLE_CURSOR_MISSING' using errcode='55000';
  end if;
  perform public.master_v2_lock_scope(p_session);
  select * into strict run from public.mission_run_state
    where master_session_id=p_session for update;
  if run.run_phase <> 'in_corso' or m.closed_at is not null then
    raise exception 'MSR_RUN_NOT_ACTIVE' using errcode='55000';
  end if;
  select * into strict current_work from mission_generic_owner.work_items
    where id=p_failed_director and master_session_id=p_session for update;
  if current_work.kind <> 'director' or current_work.state <> 'failed'
    or current_work.result->>'provider_calls' <> '1'
    or current_work.result->>'outcome_uncertain' <> 'false'
    or not (current_work.result->'failure_codes' ? 'MISSION_DIRECTOR_STATIC_PROGRESS_REJECTED')
    or current_work.finalized_at is null then
    raise exception 'MSR_DIRECTOR_NOT_ELIGIBLE' using errcode='55000';
  end if;
  select * into strict current_window from mission_generic_owner.unified_source_windows
    where id=current_work.authority_receipt_id and work_id=current_work.id
      and master_session_id=p_session for update;
  if current_window.superseded_at is not null
    or current_window.consumed_message_id is not null
    or current_window.step_key <> run.current_step_key
    or current_window.run_control_version <> run.control_version
    or current_work.payload_sha256 <> current_window.source_sha256
    or current_work.definition_sha256 <> current_window.definition_sha256
    or current_window.context->>'source_revision' is distinct from
      mission_generic_owner.role_source_revision_v1(p_session)
    or exists(select 1 from public.combat_v2_sessions combat
       where combat.master_session_id=p_session and combat.state='in_corso') then
    raise exception 'MSR_CURRENT_WINDOW_CHANGED' using errcode='40001';
  end if;

  select * into strict previous_batch from mission_generic_owner.unified_batches
    where master_session_id=p_session and state<>'published' for update;
  if previous_batch.source_window_id=current_window.id then
    select * into new_writer from mission_generic_owner.work_items
      where id=previous_batch.writer_work_id and master_session_id=p_session;
    if previous_batch.state='ready'
      and previous_batch.composition_kind='narrative_continuation'
      and previous_batch.decision->>'source_window_id'=current_window.id::text
      and new_writer.id is not null
      and new_writer.authority_receipt_id=previous_batch.id
      and new_writer.dedupe_key='unified-recovery:'||previous_batch.id::text||':'||current_window.id::text
      and new_writer.payload_sha256=previous_batch.payload_sha256
      and exists(select 1 from mission_narrative_internal.dispatch_audit da
        where da.event_code='staff_identical_role_recovery'
          and da.details->>'master_session_id'=p_session::text
          and da.details->>'current_failed_director_id'=current_work.id::text
          and da.details->>'batch_id'=previous_batch.id::text
          and da.details->>'new_writer_id'=new_writer.id::text) then
      return jsonb_build_object('schema_version','mission-staff-role-resume/1',
        'replayed',true,'work',mission_generic_owner.work_status(new_writer));
    end if;
    raise exception 'MSR_REPLAY_CONFLICT' using errcode='55000';
  end if;
  if exists(select 1 from mission_generic_owner.work_items w
       where w.master_session_id=p_session and w.created_at>current_work.created_at) then
    raise exception 'MSR_NEWER_WORK' using errcode='40001';
  end if;
  select * into strict previous_window from mission_generic_owner.unified_source_windows
    where id=previous_batch.source_window_id and master_session_id=p_session for update;
  select * into strict previous_director from mission_generic_owner.work_items
    where id=previous_batch.decision_work_id for share;
  select * into strict previous_writer from mission_generic_owner.work_items
    where id=previous_batch.writer_work_id for update;
  select * into strict previous_receipt from mission_narrative_internal.dispatch_receipts
    where id=previous_writer.dispatch_receipt_id for share;
  if previous_batch.state <> 'needs_review'
    or previous_batch.composition_kind <> 'narrative_continuation'
    or previous_batch.encounter_id is not null or previous_batch.encounter_key is not null
    or previous_batch.entry_side is not null or previous_batch.route is not null
    or previous_batch.message_id is not null or previous_batch.next_round_id is not null
    or previous_batch.master_session_id <> current_window.master_session_id
    or previous_batch.step_key <> current_window.step_key
    or previous_batch.run_control_version <> current_window.run_control_version
    or previous_window.definition_sha256 <> current_window.definition_sha256
    or previous_window.superseded_reason <> 'new_role_before_provider'
    or not mission_generic_owner.role_source_released_v4(previous_window.id)
    or previous_director.state <> 'completed'
    or previous_director.result->'decision' is distinct from previous_batch.decision
    or previous_writer.state <> 'failed' or previous_writer.finalized_at is null
    or previous_writer.result->>'provider_calls' <> '0'
    or previous_receipt.status <> 'failed' or previous_receipt.dispatch_count <> 0
    or previous_receipt.charged_cost_usd is distinct from 0
    or cardinality(previous_window.role_ids) <> cardinality(current_window.role_ids)
    or exists(select 1 from public.messages fato
       where fato.location_id=m.location_id and fato.kind='fato'
         and fato.created_at>previous_batch.created_at)
    or exists(select 1 from mission_generic_owner.work_items w
       where w.master_session_id=p_session and w.state in
         ('ready','claimed','authorized','provider_started','uncertain')) then
    raise exception 'MSR_PREVIOUS_BATCH_NOT_ELIGIBLE' using errcode='55000';
  end if;
  -- Every participant must have the same submitted text, not merely the same
  -- number of roles. The current role must still be the latest valid one.
  if exists(select 1 from mission_generic_owner.role_submissions old_role_submission
       where old_role_submission.message_id=any(previous_window.role_ids)
         and not exists(select 1 from mission_generic_owner.role_submissions new_role_submission
           where new_role_submission.message_id=any(current_window.role_ids)
             and new_role_submission.user_id=old_role_submission.user_id
             and new_role_submission.body_sha256=old_role_submission.body_sha256
             and new_role_submission.valid))
    or exists(select 1 from mission_generic_owner.role_submissions new_role_submission
       where new_role_submission.message_id=any(current_window.role_ids)
         and not exists(select 1 from mission_generic_owner.role_latest_v1(p_session) latest
           where latest.message_id=new_role_submission.message_id and latest.valid)) then
    raise exception 'MSR_ROLES_DIFFER' using errcode='40001';
  end if;
  recovered_decision := previous_batch.decision;
  if recovered_decision->>'schema_version'<>'mission-director-proposal/2'
    or recovered_decision->>'entry_side' is not null
    or recovered_decision->'npc_intents'<>'[]'::jsonb
    or recovered_decision->>'opportunity_id' is null then
    raise exception 'MSR_DECISION_SCOPE' using errcode='55000';
  end if;
  select opportunity into strict selected_old
    from jsonb_array_elements(previous_window.opportunities) opportunity
    where opportunity->>'opportunity_id'=recovered_decision->>'opportunity_id';
  if selected_old->>'encounter_key' is not null then
    raise exception 'MSR_COMBAT_NOT_ELIGIBLE' using errcode='55000';
  end if;
  select count(*),min(opportunity::text)::jsonb into matching_count,selected_new
    from jsonb_array_elements(current_window.opportunities) opportunity
    where opportunity-'opportunity_id'-'destination_context'
        =selected_old-'opportunity_id'-'destination_context'
      and (opportunity->'destination_context')-'source_revision'-'source_cursor'-'authority_receipt_id'
        =(selected_old->'destination_context')-'source_revision'-'source_cursor'-'authority_receipt_id';
  if matching_count<>1 or selected_new->>'action_kind' is distinct from recovered_decision->>'action_kind'
    or selected_new->>'encounter_key' is not null
    or selected_new#>>'{destination_context,step_key}' is null then
    raise exception 'MSR_OPPORTUNITY_DRIFT' using errcode='40001';
  end if;
  for old_role in select value::uuid from jsonb_array_elements_text(recovered_decision->'source_role_ids') loop
    select new_submission.message_id into strict new_role
      from mission_generic_owner.role_submissions old_submission
      join mission_generic_owner.role_submissions new_submission
        on new_submission.user_id=old_submission.user_id
          and new_submission.body_sha256=old_submission.body_sha256
      where old_submission.message_id=old_role
        and new_submission.message_id=any(current_window.role_ids);
    mapped_roles:=mapped_roles||jsonb_build_array(new_role::text);
  end loop;
  for evidence in select value from jsonb_array_elements(recovered_decision->'source_evidence') loop
    old_role:=(evidence->>'role_id')::uuid;
    select new_submission.message_id into strict new_role
      from mission_generic_owner.role_submissions old_submission
      join mission_generic_owner.role_submissions new_submission
        on new_submission.user_id=old_submission.user_id
          and new_submission.body_sha256=old_submission.body_sha256
      where old_submission.message_id=old_role
        and new_submission.message_id=any(current_window.role_ids);
    mapped_evidence:=mapped_evidence||jsonb_build_array(
      jsonb_set(evidence,'{role_id}',to_jsonb(new_role::text)));
  end loop;
  recovered_decision:=recovered_decision||jsonb_build_object(
    'source_window_id',current_window.id,
    'source_role_ids',mapped_roles,
    'source_evidence',mapped_evidence,
    'opportunity_id',selected_new->>'opportunity_id');
  update mission_generic_owner.unified_batches batch set
    state='preparing',source_window_id=current_window.id,decision=recovered_decision,
    decision_sha256=public.combat_v2_sha256(recovered_decision),writer_work_id=null,
    payload=null,payload_sha256=null,
    context=mission_generic_owner.npc_entry_visible_context(
      jsonb_set(selected_new->'destination_context','{source_revision}',
        to_jsonb(current_window.context->>'source_revision'),true),
      mission_generic_owner.scene(p_session,selected_new#>>'{destination_context,step_key}'),
      previous_batch.id)
    where batch.id=previous_batch.id;
  -- A failed writer keeps its original event/dedupe keys. Reusing the normal
  -- enqueuer would collide with both unique indexes on work_items.
  writer_payload:=mission_generic_owner.unified_batch_payload(previous_batch.id);
  select * into strict run_binding from mission_generic_owner.run_bindings
    where master_session_id=p_session;
  insert into mission_generic_owner.work_items(
    master_session_id,event_id,dedupe_key,step_key,run_control_version,
    definition_sha256,encounter_id,authority_receipt_id,kind,revision,
    payload,payload_sha256)
  values(p_session,gen_random_uuid(),
    'unified-recovery:'||previous_batch.id::text||':'||current_window.id::text,
    previous_batch.step_key,previous_batch.run_control_version,
    run_binding.snapshot_sha256,null,previous_batch.id,'narration',
    previous_batch.run_control_version,writer_payload,
    public.combat_v2_sha256(writer_payload))
  returning * into new_writer;
  update mission_generic_owner.unified_batches set
    state='ready',payload=writer_payload,
    payload_sha256=public.combat_v2_sha256(writer_payload),writer_work_id=new_writer.id
    where id=previous_batch.id;
  perform mission_generic_owner.work_assert(new_writer);
  recovered:=mission_generic_owner.work_status(new_writer);
  insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    values(previous_receipt.id,'staff_identical_role_recovery',
      jsonb_build_object('master_session_id',p_session,
        'current_failed_director_id',current_work.id,
        'previous_window_id',previous_window.id,
        'current_window_id',current_window.id,'previous_writer_id',previous_writer.id,
        'new_writer_id',new_writer.id,'batch_id',previous_batch.id,
        'previous_decision_sha256',previous_batch.decision_sha256,
        'previous_context_sha256',public.combat_v2_sha256(previous_batch.context),
        'remapped_decision_sha256',public.combat_v2_sha256(recovered_decision),
        'writer_payload_sha256',new_writer.payload_sha256));
  return jsonb_build_object('schema_version','mission-staff-role-resume/1',
    'replayed',false,'work',recovered);
end;
$function$

