    or recovered_decision->'npc_intents'<>'[]'::jsonb
    or recovered_decision->>'opportunity_id' is null then
    raise exception 'MSR_DECISION_SCOPE' using errcode='55000';
  end if;
  select opportunity into strict selected_old
    from jsonb_array_elements(previous_window.opportunities) opportunity
    where opportunity->>'opportunity_id'=recovered_decision->>'opportunity_id';
  if selected_old->>'encounter_key' is not null then
    raise exception 'MSR_COMBAT_NOT_ELIGIBLE' using errcode='55000';
  end if;
  select count(*),min(opportunity::text)::jsonb into matching_count,selected_new
    from jsonb_array_elements(current_window.opportunities) opportunity
    where opportunity-'opportunity_id'-'destination_context'
